INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch05$PT159-S1-Q6$batch05$, 159, 1, 6, $batch05$Necessary Assumption$batch05$, $batch05$Prominent government officials have denied that their policies have produced serious environmental degradation. But the facts show otherwise. Last year, at the urging of certain mining companies, the government repealed a long-standing provision prohibiting the dumping of mining wastes into streams. Since that time, hundreds of miles of vital streams have been buried under bulldozed mining wastes.$batch05$, $batch05$The argument relies on which one of the following assumptions?$batch05$, $batch05$E$batch05$, true, $batch05$Batch 05; question text from local bank.$batch05$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q6$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$A$batch05$, $batch05$Without the urging of certain mining companies, the government would not have lifted the ban on dumping mining wastes into streams.$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q6$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$A$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$B$batch05$, $batch05$The prominent government officials who deny that government policies have produced serious environmental degradation do not really believe what they are claiming.$batch05$, $batch05$Out of Scope$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q6$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$B$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$C$batch05$, $batch05$The mining companies that urged repeal of the ban on dumping mining wastes in streams were among those that buried hundreds of miles of streams under mining wastes.$batch05$, $batch05$Not Necessary$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q6$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$C$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$D$batch05$, $batch05$The government is generally more responsive to pressures from the mining industry than from environmentalists.$batch05$, $batch05$Irrelevant Comparison$batch05$, false FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q6$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$D$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch05$E$batch05$, $batch05$If the ban on dumping mining wastes in streams had not been repealed, considerably less mining waste would have found its way into streams.$batch05$, $batch05$Correct$batch05$, true FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q6$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch05$E$batch05$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT159-S1-Q6$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Government policies have caused serious environmental damage, contrary to the officials' denials.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$The government repealed the ban on dumping mining waste into streams. Since then, hundreds of miles of streams have been buried under it.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$This is a before-and-after argument: the ban went away, then the streams were buried. To blame the *policy*, the repeal has to make a difference. If the mining waste would have ended up in the streams anyway (say, the ban was widely ignored), the repeal caused nothing.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A defender: without the repeal, much less waste would have reached the streams.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT159-S1-Q6$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Why the government lifted the ban does not matter. What matters is what happened after.$batch05$), ($batch05$B$batch05$, $batch05$Whether the officials believe their own denials does not affect whether the policy caused damage.$batch05$), ($batch05$C$batch05$, $batch05$It does not matter which companies did the dumping, only that the repeal led to it.$batch05$), ($batch05$D$batch05$, $batch05$Comparing the mining industry with environmentalists does not connect the policy to the damage.$batch05$), ($batch05$E$batch05$, $batch05$Negate it: "even with the ban, about the same amount of waste would have reached the streams." Then the buried streams are not the policy's doing, and the facts no longer contradict the officials.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT159-S1-Q6$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
